export function getTranslatedLiuGongSparePartDetails(partName: string, language: string = 'en'): string {
  const translations = liugongPartDetailsTranslations[partName];
  if (translations && translations[language]) {
    return translations[language];
  }
  // Fallback to English if translation not found
  if (translations && translations['en']) {
    return translations['en'];
  }
  // Default fallback
  return 'OEM quality part. Contact us for detailed specifications and pricing.';
}
